css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .6); position: relative; display: grid; place-items: center; }
.loader::before, .loader::after { content: ''; position: absolute; top: 0; width: 14%; height: 100%; border-radius: 4px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 32%, var(--accent))); }
.loader::before { left: 0; }
.loader::after { right: 0; }
.loader .bellows { height: 82%; border-radius: 2px; background: repeating-linear-gradient(90deg, var(--accent-2) 0 8%, color-mix(in srgb, #000 28%, var(--accent-2)) 8% 16%); animation: squeeze calc(var(--loader-speed) * 2) ease-in-out infinite; }
@keyframes squeeze { 0%, 100% { width: 76%; } 50% { width: 40%; } }
